# 서비스 계정(Service Account) 예시: Python 3에서 실행 가능한 코드
account = {"name": "batch-job", "permissions": ["read_bucket"]}
print(account["name"], account["permissions"])

# 클라우드 IAM 심화 예시: Python 3에서 실행 가능한 코드
policy = {"action": "s3:GetObject", "resource": "reports/*"}
print(policy["action"])

# 리소스 기반 정책 예시: Python 3에서 실행 가능한 코드
bucket_policy = {"principal": "analytics-role", "action": "read"}
print(bucket_policy["principal"])

# 조직 단위(OU) 예시: Python 3에서 실행 가능한 코드
ou = {"name": "prod", "accounts": ["a1", "a2"]}
print(len(ou["accounts"]))

# 랜딩 존(Landing Zone) 예시: Python 3에서 실행 가능한 코드
landing_zone = {"logging": True, "network": True, "guardrails": True}
print(all(landing_zone.values()))

# FinOps 예시: Python 3에서 실행 가능한 코드
cost = {"teamA": 120, "teamB": 80}
print(sum(cost.values()))

# 태깅 전략 예시: Python 3에서 실행 가능한 코드
tags = {"team": "data", "env": "prod", "owner": "kim"}
required = {"team", "env", "owner"}
print(required <= set(tags))

# 서비스 계정 토큰 예시: Python 3에서 실행 가능한 코드
token = {"aud": "k8s", "expires_in": 3600}
print(token["expires_in"] <= 3600)

# Kyverno 예시: Python 3에서 실행 가능한 코드
pod = {"runAsNonRoot": True}
print(pod.get("runAsNonRoot") is True)

# 네트워크 정책(K8s) 예시: Python 3에서 실행 가능한 코드
allowed = {("api", "db")}
print(("web", "db") in allowed)

# Pod 보안 표준 예시: Python 3에서 실행 가능한 코드
pod = {"privileged": False, "runAsRoot": False}
print(not pod["privileged"] and not pod["runAsRoot"])

# 시크릿 관리(Vault) 예시: Python 3에서 실행 가능한 코드
vault = {"db_password": "rotated"}
print("db_password" in vault)

# GitOps 심화 예시: Python 3에서 실행 가능한 코드
desired = {"version": "2", "policy": "restricted"}
live = {"version": "1", "policy": "restricted"}
print(desired != live)

# 드리프트 감지 예시: Python 3에서 실행 가능한 코드
desired = {"replicas": 3}
actual = {"replicas": 2}
print(desired != actual)

# 멀티클러스터 관리 예시: Python 3에서 실행 가능한 코드
clusters = {"prod-kr": "ok", "prod-us": "ok"}
print(len(clusters))

# 서비스 메시 심화 예시: Python 3에서 실행 가능한 코드
features = {"mTLS": True, "traffic_split": True, "retry": True}
print(all(features.values()))

# 웨스트-이스트 트래픽 예시: Python 3에서 실행 가능한 코드
traffic = {"frontend->api": "north-south", "api->db": "east-west"}
print(traffic["api->db"])

# OpenTelemetry 예시: Python 3에서 실행 가능한 코드
span = {"trace_id": "abc", "name": "GET /api"}
print(span["trace_id"])

# 리호스팅 예시: Python 3에서 실행 가능한 코드
app = {"changed_code": False, "target": "cloud_vm"}
print(app)

# 클라우드 탈출 전략 예시: Python 3에서 실행 가능한 코드
exit_plan = {"data_export": True, "alt_provider": True}
print(all(exit_plan.values()))

# 오픈소스 대안 선택 예시: Python 3에서 실행 가능한 코드
option = {"license": "Apache-2.0", "maintained": True}
print(option["maintained"])

# AWS EKS 예시: Python 3에서 실행 가능한 코드
eks = {"control_plane": "managed", "workers": "user"}
print(eks["control_plane"])

# GKE(Google Kubernetes Engine) 예시: Python 3에서 실행 가능한 코드
gke = {"mode": "autopilot", "workload_identity": True}
print(gke["mode"])

# AKS(Azure Kubernetes) 예시: Python 3에서 실행 가능한 코드
aks = {"aad": True, "acr": True}
print(all(aks.values()))

# EventBridge 예시: Python 3에서 실행 가능한 코드
rule = {"source": "orders", "target": "billing"}
event = {"source": "orders"}
print(rule["target"] if event["source"] == rule["source"] else None)

# Kinesis 스트리밍 예시: Python 3에서 실행 가능한 코드
shards = {0: ["e1"], 1: ["e2", "e3"]}
print(sum(len(v) for v in shards.values()))
